SET LOCAL aidash.scope = 'deployment';
UPDATE "conversations" SET "scratch_space_id" = gen_random_uuid();
INSERT INTO "scratch_spaces" ("id", "tenant", "node", "name", "creator", "state", "created_at", "last_used_at") SELECT "c"."scratch_space_id", "c"."tenant", "w"."node", "w"."title", "c"."created_by", 'active', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM "conversations" AS "c" INNER JOIN "workspaces" AS "w" ON "c"."workspace_id" = "w"."id";
INSERT INTO "scratch_space_settings" ("space_id", "tenant", "settings") SELECT "scratch_space_id", "tenant", '{"allowed_hosts":{"hosts":["archive.ubuntu.com","auth.docker.io","crates.io","deb.debian.org","files.pythonhosted.org","ghcr.io","github.com","index.crates.io","objects.githubusercontent.com","proxy.golang.org","pypi.org","quay.io","registry-1.docker.io","registry.npmjs.org","security.ubuntu.com","static.crates.io","sum.golang.org"],"kind":"hosts"},"capacity_bytes":107374182400,"cpu_millis":4000,"daily_received_bytes":107374182400,"daily_sent_bytes":107374182400,"docker_enabled":false,"execution_image":null,"external_services":[],"idle_expiry_days":14,"memory_bytes":17179869184}' FROM "conversations";
